package com.complaintbox.controller; import com.complaintbox.entity.*; import com.complaintbox.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/notifications") public class NotificationController{final NotificationRepository repo;final ResidentRepository residents;final StaffRepository staff;public NotificationController(NotificationRepository r,ResidentRepository re,StaffRepository s){repo=r;residents=re;staff=s;}@GetMapping Object list(HttpSession s){Object role=s.getAttribute("ROLE");if("STUDENT".equals(role)){Resident r=residents.findById((Long)s.getAttribute("RESIDENT_ID")).orElseThrow();return repo.findByResidentOrderByCreatedAtDesc(r);}Staff x=staff.findById((Long)s.getAttribute("STAFF_ID")).orElseThrow();return repo.findByStaffOrderByCreatedAtDesc(x);}@PatchMapping("/{id}/read")Object read(@PathVariable Long id,HttpSession s){Notification n=repo.findById(id).orElseThrow();n.setRead(true);repo.save(n);return Map.of("success",true);}@PatchMapping("/read-all")Object all(HttpSession s){Object role=s.getAttribute("ROLE");List<Notification> list;if("STUDENT".equals(role)){Resident r=residents.findById((Long)s.getAttribute("RESIDENT_ID")).orElseThrow();list=repo.findByResidentOrderByCreatedAtDesc(r);}else{Staff x=staff.findById((Long)s.getAttribute("STAFF_ID")).orElseThrow();list=repo.findByStaffOrderByCreatedAtDesc(x);}list.forEach(x->x.setRead(true));repo.saveAll(list);return Map.of("success",true);}}
